import gurobipy as gp
from gurobipy import GRB

# Define sets
bakeries = ['Greenville', 'Springfield', 'Riverside', 'Hilltop']
stores = ['Maplewood', 'Oakdale', 'Pineville', 'Cedarhurst', 'Brookside']

# Define parameters
S = {
    'Greenville': 200,
    'Springfield': 150,
    'Riverside': 250,
    'Hilltop': 180
}

D = {
    'Maplewood': 120,
    'Oakdale': 100,
    'Pineville': 130,
    'Cedarhurst': 90,
    'Brookside': 80
}

# Distances
d = {
    'Greenville': [10, 15, 20, 25, 30],
    'Springfield': [12, 8, 18, 22, 28],
    'Riverside': [14, 10, 16, 20, 26],
    'Hilltop': [16, 12, 14, 18, 24]
}

# Calculate costs
c = {}
for i in bakeries:
    c[i] = {}
    for j_idx, j in enumerate(stores):
        c[i][j] = (d[i][j_idx]) ** 0.5

# Create model
model = gp.Model(env=env)

# Add variables
x = {}
for i in bakeries:
    for j in stores:
        x[(i, j)] = model.addVar(vtype=GRB.INTEGER, name=f"x_{i}_{j}")

# Objective
model.setObjective(gp.quicksum(c[i][j] * x[(i, j)] for i in bakeries for j in stores), GRB.MINIMIZE)

# Constraints
# Supply
for i in bakeries:
    model.addConstr(gp.quicksum(x[(i, j)] for j in stores) <= S[i], f"Supply_{i}")

# Demand
for j in stores:
    model.addConstr(gp.quicksum(x[(i, j)] for i in bakeries) == D[j], f"Demand_{j}")

# Optimize
model.optimize()

# Check status and print results
if model.status == GRB.OPTIMAL:
    # Print x values
    for i in bakeries:
        for j in stores:
            print(f"x_{i}_{j} = {x[(i, j)].X}")
    # Print objective
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found")
```

