import gurobipy as gp
from gurobipy import GRB

# Create model
model = gp.Model()

# Sets
T = [1, 2]
P = ['X', 'Y']

# Parameters
D = {('X', 1): 100, ('Y', 1): 200, ('X', 2): 300, ('Y', 2): 100}
Cap = {1: 1500, 2: 1500}
M = {'X': 4, 'Y': 3}
C_mat = {1: 300, 2: 450}
L_max = 2500
I_init = {'X': 200, 'Y': 300}
C_store = 100
E = {'X': 0.85, 'Y': 0.95}
E_min = 0.90

# Variables
P_vars = {}
for p in P:
    for t in T:
        P_vars[(p, t)] = model.addVar(lb=0, name=f"P_{p}_{t}")

I_vars = {}
for p in P:
    for t in T:
        I_vars[(p, t)] = model.addVar(lb=0, name=f"I_{p}_{t}")

R_vars = {}
for t in T:
    R_vars[t] = model.addVar(lb=0, name=f"R_{t}")

# Objective
mat_cost = gp.quicksum(C_mat[t] * R_vars[t] for t in T)
store_cost = gp.quicksum(C_store * I_vars[(p, t)] for t in T for p in P)
model.setObjective(mat_cost + store_cost, GRB.MINIMIZE)

# Constraints
# 1. Inventory Balance
for p in P:
    for t in T:
        if t == 1:
            start_inv = I_init[p]
        else:
            start_inv = I_vars[(p, t - 1)]
        model.addConstr(I_vars[(p, t)] == start_inv + P_vars[(p, t)] - D[(p, t)], name=f"InvBal_{p}_{t}")

# 2. Production Capacity
for t in T:
    model.addConstr(gp.quicksum(P_vars[(p, t)] for p in P) <= Cap[t], name=f"Cap_{t}")

# 3. Material Usage
for t in T:
    model.addConstr(gp.quicksum(M[p] * P_vars[(p, t)] for p in P) <= R_vars[t], name=f"MatUse_{t}")

# 4. Material Purchase Limit
for t in T:
    model.addConstr(R_vars[t] <= L_max, name=f"MatLim_{t}")

# 5. Efficacy Requirement
for t in T:
    model.addConstr(gp.quicksum(E[p] * P_vars[(p, t)] for p in P) >= E_min * gp.quicksum(P_vars[(p, t)] for p in P), name=f"Efficacy_{t}")

# Optimize
model.optimize()

# Output
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
```

