import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Sets
parcels = [1, 2, 3, 4, 5, 6, 7, 8]
trucks = [1, 2, 3]
pairs = [(1, 3), (2, 5), (2, 6), (4, 8), (5, 7)]

# Parameters
capacities = {1: 100, 2: 120, 3: 80}
weights = {1: 35, 2: 45, 3: 25, 4: 50, 5: 30, 6: 40, 7: 20, 8: 55}
revenues = {1: 50, 2: 75, 3: 40, 4: 80, 5: 60, 6: 65, 7: 35, 8: 90}
bonuses = {(1, 3): 25, (2, 5): 30, (2, 6): 20, (4, 8): 40, (5, 7): 22}

# Decision Variables
# x[p][t]
x_vars = {}
for p in parcels:
    for t in trucks:
        x_vars[(p, t)] = model.addVar(vtype=GRB.BINARY, name=f"x_{p}_{t}")

# y[p][q][t]
y_vars = {}
for p, q in pairs:
    for t in trucks:
        y_vars[(p, q, t)] = model.addVar(vtype=GRB.BINARY, name=f"y_{p}_{q}_{t}")

# Constraints
# Assignment: each parcel to exactly one truck
for p in parcels:
    model.addConstr(gp.quicksum(x_vars[(p, t)] for t in trucks) == 1, name=f"assign_{p}")

# Capacity: weight limit for each truck
for t in trucks:
    model.addConstr(gp.quicksum(weights[p] * x_vars[(p, t)] for p in parcels) <= capacities[t], name=f"cap_{t}")

# Synergy Logic
for p, q in pairs:
    for t in trucks:
        model.addConstr(y_vars[(p, q, t)] <= x_vars[(p, t)], name=f"y_le_x_p_{p}_{q}_{t}")
        model.addConstr(y_vars[(p, q, t)] <= x_vars[(q, t)], name=f"y_le_x_q_{p}_{q}_{t}")
        model.addConstr(y_vars[(p, q, t)] >= x_vars[(p, t)] + x_vars[(q, t)] - 1, name=f"y_ge_x_pq_{p}_{q}_{t}")

# Objective
obj = 0
for p in parcels:
    for t in trucks:
        obj += revenues[p] * x_vars[(p, t)]
for p, q in pairs:
    for t in trucks:
        obj += bonuses[(p, q)] * y_vars[(p, q, t)]
model.setObjective(obj, GRB.MAXIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

