from gurobipy import GRB
import math

# Coordinates
coords = {
    0: (0.0, 0.0),
    1: (3.5, 4.2),
    2: (-2.1, 5.6),
    3: (4.8, -3.2),
    4: (-3.6, -2.8),
    5: (5.2, 2.4),
    6: (-4.1, 3.7),
    7: (2.8, -4.5),
    8: (6.3, -2.1),
    9: (-5.2, -1.8),
    10: (3.9, 5.8)
}

n = 10
nodes = list(range(n + 1))

# Precompute distances
dist = {}
for i in nodes:
    for j in nodes:
        if i != j:
            dx = coords[i][0] - coords[j][0]
            dy = coords[i][1] - coords[j][1]
            dist[(i, j)] = math.sqrt(dx**2 + dy**2)

model = gp.Model(env=env)

# Decision variables
# x_ij binary
x = {}
for i in nodes:
    for j in nodes:
        if i != j:
            x[(i, j)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# u_i integer for i in 1..n
u = {}
for i in range(1, n + 1):
    u[i] = model.addVar(vtype=GRB.INTEGER, lb=1, ub=n - 1, name=f"u_{i}")

# Constraints
# Flow conservation: sum x_ij = 1 for each j
for j in nodes:
    model.addConstr(gp.quicksum(x[(i, j)] for i in nodes if i != j) == 1, name=f"enter_{j}")

# Flow conservation: sum x_ij = 1 for each i
for i in nodes:
    model.addConstr(gp.quicksum(x[(i, j)] for j in nodes if j != i) == 1, name=f"leave_{i}")

# Subtour elimination
# u_i - u_j + n * x_ij <= n - 1 for i, j in {1..n}, i != j
for i in range(1, n + 1):
    for j in range(1, n + 1):
        if i != j:
            model.addConstr(u[i] - u[j] + n * x[(i, j)] <= n - 1, name=f"subtour_{i}_{j}")

# Objective
model.setObjective(gp.quicksum(dist[(i, j)] * x[(i, j)] for i in nodes for j in nodes if i != j), GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
