vans = [1, 2]
zones = ['A', 'B', 'C']

# Decision Variables
x = {}
for v in vans:
    for j in zones:
        x[(v, j)] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"x_{v}_{j}")

