for v in vans:
    model.addConstr(gp.quicksum(x[(v, j)] for j in zones) <= Cap[v] * y[v], name=f"Capacity_{v}")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
